import React, { useEffect, useState } from "react";
import Box from '@mui/material/Box';
import Card from '@mui/material/Card';
import Select from '@mui/material/Select'
import { styled } from '@mui/material/styles';
import FormControl from '@mui/material/FormControl';
import FormControlLabel from '@mui/material/FormControlLabel';
import Switch from '@mui/material/Switch';
import { MenuItem, Button, Typography, Grid, InputLabel } from '@mui/material';
import { axios } from "../utils/axios";
import GenerateToastConfig from '../components/toast-config/GenerateToastConfig';
import InputField from "../components/input/inputField";
import { useMyContext } from "./provider";

const IOSSwitch = styled((props) => (
    <Switch focusVisibleClassName=".Mui-focusVisible" disableRipple {...props} />
))(({ theme }) => ({
    width: 42,
    height: 26,
    padding: 0,
    '& .MuiSwitch-switchBase': {
        padding: 0,
        margin: 2,
        transitionDuration: '300ms',
        '&.Mui-checked': {
            transform: 'translateX(16px)',
            color: '#fff',
            '& + .MuiSwitch-track': {
                backgroundColor: theme.palette.mode === 'dark' ? '#66b2a5' : '#222',
                opacity: 1,
                border: 0,
            },
            '&.Mui-disabled + .MuiSwitch-track': {
                opacity: 0.5,
            },
        },
        '&.Mui-focusVisible .MuiSwitch-thumb': {
            color: '#33cf4d',
            border: '6px solid #fff',
        },
        '&.Mui-disabled .MuiSwitch-thumb': {
            color:
                theme.palette.mode === 'light'
                    ? theme.palette.grey[100]
                    : theme.palette.grey[600],
        },
        '&.Mui-disabled + .MuiSwitch-track': {
            opacity: theme.palette.mode === 'light' ? 0.7 : 0.3,
        },
    },
    '& .MuiSwitch-thumb': {
        boxSizing: 'border-box',
        width: 22,
        height: 22,
    },
    '& .MuiSwitch-track': {
        borderRadius: 26 / 2,
        backgroundColor: theme.palette.mode === 'light' ? '#E9E9EA' : '#39393D',
        opacity: 1,
        transition: theme.transitions.create(['background-color'], {
            duration: 500,
        }),
    },
}));

export default function Settings() {
    const [sensitive, setSensitive] = useState('0');
    const [mode, setMode] = useState('0');
    const [checkin, setCheckin] = useState('0');
    const [time, setTime] = useState('0');
    const [input, setInput] = useState('0');
    const [settingData, setSettingData] = useState()
    const [bookingType, setBookingType] = useState('0')
    const [dateFormat, setDateFormat] = useState('DD-MM-YYYY');
    const [timeFormat, setTimeFormat] = useState("hh:mm A");
    const [themeColor, setThemeColor] = useState('');
    const [limitImages, setLimitImages] = useState('');
    const [autoEnable, setAutoEnable] = useState("1")
    const [specification, setSpecification] = useState('0')
    const [pricingAddition, setPricingAddition] = useState('0')
    const [documentsAddition, setDocumentsAddition] = useState('0')
    const [adsAddition, setAdsAddition] = useState('0');
    const [listing, setListing] = useState('0');
    const [availableCountAddition, setAvailableCountAddition] = useState('0')
    const [themeToggle, setThemeToggle] = useState('0');
    const [calenderTheme, setCalenderTheme] = useState('0');
    const [Stripe, setStripe] = useState('0');
    const [razorpay, setRazorpay] = useState('0');
    const [cash, setCash] = useState('0');
    const [mapOption, setMapOption] = useState('0');
    const [primaryTheme, setPrimaryTheme] = useState();
    const [secondaryTheme, setSecondaryTheme] = useState();
    const { i18 } = useMyContext
    const limitOptions = ["Default", "1", "2", "3", "4", "5"];

    const handleChangeDateFormat = (event) => {
        setDateFormat(event.target.value);
    };

    const handleChangeTimeFormat = (event) => {
        setTimeFormat(event.target.value);
    };

    const handleThemeSelection = (event) => {
        setThemeColor(event.target.value);
    };

    const handlelistingImages = (event) => {
        setLimitImages(event.target.value)
    }

    const settingGetData = async () => {
        try {
            const res = await axios.get('module/settings');
            if (res.status === 200) {
                setSettingData(res.data.data);
            }
        } catch (err) {
            console.log(err);
        }
    };

    const handleChangeSensitive = (event) => {
        setSensitive(event.target.checked ? "1" : "0");
    };

    const handleChangeMode = (event) => {
        setMode(event.target.checked ? "1" : "0");
    }

    const handleAutoEnable = (event) => {
        setAutoEnable(event.target.checked ? "1" : "0")
    }
    const handlePricingAddition = (event) => {
        setPricingAddition(event.target.checked ? "1" : "0")
    }
    const handleDocumentsAddition = (event) => {
        setDocumentsAddition(event.target.checked ? "1" : "0")
    }
    const handleAdsToggle = (event) => {
        if (listing === '0' && event.target.checked === false) {
            setListing("1");
        }
        setAdsAddition(event.target.checked ? "1" : "0");
    }
    const handleListingToggle = (event) => {
        if (adsAddition === '0' && event.target.checked === false) {
            setAdsAddition("1");
        }
        setListing(event.target.checked ? "1" : "0");
    }

    const handleAvailableCount = (event) => {
        setAvailableCountAddition(event.target.checked ? "1" : "0");
    }
    const handleStripe = (event) => {
        setStripe(event.target.checked ? "1" : "0");
    }
    const handleRazorpay = (event) => {
        setRazorpay(event.target.checked ? "1" : "0");
    }
    const handleCash = (event) => {
        setCash(event.target.checked ? "1" : "0");
    }
    const handleMapOption = (event) => {
        setMapOption(event.target.checked ? "1" : "0");
    }
    const handleThemeToggle = (event) => {
        setThemeToggle(event?.target?.checked ? "1" : "0");
    }
    const handleCalenderToggle = (event) => {
        setCalenderTheme(event?.target?.checked ? "1" : "0");
    }
    const handleSpecification = (event) => {
        setSpecification(event.target.checked ? "1" : "0")
    }
    const handleChangeBookingType = (event) => {
        setBookingType(event.target.value)
    }
    const handleChangeInput = (event) => {
        setInput(event.target.checked ? "1" : "0");
    }
    const handleSecondaryTheme = (event) => {
        setSecondaryTheme(event.target.value);
    };
    const handlePrimaryTheme = (event) => {
        setPrimaryTheme(event.target.value);
    }

    const editSettings = async () => {
        const formData = new FormData();
        formData.append('sensitive', sensitive === "1" ? "1" : "0");
        formData.append('mode', mode === "1" ? "1" : "0");
        formData.append('checkin', checkin === "1" ? "1" : "0");
        formData.append('peoplecount', input === "1" ? "1" : "0");
        formData.append('autoEnable', autoEnable === "1" ? "1" : "0");
        formData.append('specifications', specification === "1" ? "1" : "0");
        formData.append('pricingAddition', pricingAddition === "1" ? "1" : "0");
        formData.append('documentVerification', documentsAddition === '1' ? '1' : '0')
        formData.append('ads', adsAddition === '1' ? '1' : '0')
        formData.append('listing', listing === '1' ? '1' : '0')
        formData.append('availableCount', availableCountAddition === '1' ? '1' : '0');
        formData.append('homepage', themeToggle === '1' ? '1' : '0')
        formData.append('calendarTheme', calenderTheme === '1' ? '1' : '0');
        formData.append('hourlyBooking', bookingType);
        formData.append('dateFormat', dateFormat)
        formData.append('timeformat', timeFormat)
        formData.append('themeColor', themeColor)
        formData.append('listingImageCount', limitImages)
        formData.append('primaryTheme', primaryTheme);
        formData.append('secondaryTheme', secondaryTheme);
        formData.append('stripe', Stripe);
        formData.append('razorpay', razorpay);
        formData.append('cash', cash === "1" ? "1" : "0");
        formData.append('map', mapOption === "1" ? "1" : "0");
        if (Stripe === '0' && razorpay === '0' && cash === '0') {
            GenerateToastConfig('Select atleast 1 payment method', 'error');
        } else {
            try {
                const res = await axios.put('module/settings/update', formData);
                if (res.status === 201) {
                    settingGetData()
                    GenerateToastConfig(res.data.message, 'success');
                }
            } catch (err) {
                console.log(err);
            }
        }
    }
    useEffect(() => {
        settingGetData();
    }, []);

    useEffect(() => {
        if (settingData) {
            setMode(settingData ? settingData.hiddenSettings.mode : '')
            setSensitive(settingData ? settingData.hiddenSettings.sensitive : '')
            setCheckin(settingData ? settingData.hiddenSettings.checkIn : '')
            setInput(settingData ? settingData.hiddenSettings.peopleCount : '')
            setBookingType(settingData ? settingData.hiddenSettings.hourlyBooking : '')
            setThemeColor(settingData ? settingData?.theme?.themeColor : '')
            setLimitImages(settingData ? settingData.hiddenSettings.listingImageCount : '')
            setDateFormat(settingData ? settingData.hiddenSettings.dateFormat : 'DD-MM-YYYY')
            setTimeFormat(settingData ? settingData?.hiddenSettings?.timeFormat : 'hh:mm A')
            setAutoEnable(settingData ? settingData.hiddenSettings.autoEnable : "")
            setSpecification(settingData ? settingData.listings.specifications : "")
            setPricingAddition(settingData ? settingData.listings.pricings.additions : "")
            setDocumentsAddition(settingData ? settingData.hiddenSettings.documentVerification : "")
            setAdsAddition(settingData ? settingData.hiddenSettings.ads : "");
            setListing(settingData ? settingData.hiddenSettings.listing : "");
            setAvailableCountAddition(settingData ? settingData?.listings?.availableCount : "");
            setThemeToggle(settingData ? settingData?.theme?.homepage : "");
            setCalenderTheme(settingData ? settingData?.hiddenSettings?.calendarTheme : "");
            setSecondaryTheme(settingData ? settingData?.theme?.secondaryTheme : "");
            setPrimaryTheme(settingData ? settingData?.theme?.primaryTheme : "");
            setStripe(settingData ? settingData?.hiddenSettings?.stripe : "");
            setRazorpay(settingData ? settingData?.hiddenSettings?.razorpay : "");
            setCash(settingData ? settingData?.hiddenSettings?.cash : "");
            setMapOption(settingData ? settingData?.hiddenSettings?.map : '');
        }
    }, [settingData]);

    return (
        <>
            <Box>
                <Card sx={{ padding: '30px', marginBottom: '50px' }}>
                    <Typography sx={{ fontWeight: 'bold', fontSize: '25px', textTransform: 'capitalize' }}>ABS Settings</Typography>
                </Card>
            </Box>
            {
                settingData &&
                <>
                    <Card sx={{ padding: '20px 10px', margin: '30px 0px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Mode</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={mode === '1'}
                                        onChange={handleChangeMode}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Sensitive</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={sensitive === '1'}
                                        onChange={handleChangeSensitive}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>People Count</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={input === '1'}
                                        onChange={handleChangeInput}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Auto List Approve</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={autoEnable === '1'}
                                        onChange={handleAutoEnable}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Specification</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={specification === '1'}
                                        onChange={handleSpecification}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Pricing Addition</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={pricingAddition === '1'}
                                        onChange={handlePricingAddition}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Documents</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={documentsAddition === '1'}
                                        onChange={handleDocumentsAddition}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Advertisement</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={adsAddition === '1'}
                                        onChange={handleAdsToggle}
                                    />}
                                />
                            </div>
                        </div>

                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Listings</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={listing === '1'}
                                        onChange={handleListingToggle}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Available Count</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={availableCountAddition === '1'}
                                        onChange={handleAvailableCount}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Homepage Theme</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={themeToggle === '1'}
                                        onChange={handleThemeToggle}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Calender</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={calenderTheme === '1'}
                                        onChange={handleCalenderToggle}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Stripe</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={Stripe === '1'}
                                        onChange={handleStripe}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Razor Pay</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={razorpay === '1'}
                                        onChange={handleRazorpay}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Cash</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={cash === '1'}
                                        onChange={handleCash}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Map</Typography>
                            </div>
                            <div>
                                <FormControlLabel
                                    control={<IOSSwitch sx={{ m: 1 }}
                                        checked={mapOption === '1'}
                                        onChange={handleMapOption}
                                    />}
                                />
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: "10px" }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Booking Type</Typography>
                            </div>
                            <div>
                                <FormControl fullWidth>
                                    <InputLabel id="demo-simple-select-label">BookingType-Hour</InputLabel>
                                    <Select
                                        labelId="demo-simple-select-label"
                                        id="demo-simple-select"
                                        value={bookingType}
                                        label="BookingType"
                                        onChange={handleChangeBookingType}
                                        sx={{ minWidth: "180px", height: "50px" }}
                                    >
                                        <MenuItem value={"Day"}>Day</MenuItem>
                                        <MenuItem value={"Hour"}>Hour</MenuItem>
                                        <MenuItem value={"Both"}>Both</MenuItem>
                                    </Select>
                                </FormControl>
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: "10px" }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Date Format</Typography>
                            </div>
                            <div>
                                <FormControl fullWidth>
                                    <InputLabel id="demo-simple-select-label">DateFormat</InputLabel>
                                    <Select
                                        labelId="demo-simple-select-label"
                                        id="demo-simple-select"
                                        value={dateFormat}
                                        label="DateFormat"
                                        onChange={handleChangeDateFormat}
                                        sx={{ minWidth: "180px", height: "50px" }}
                                    >
                                        <MenuItem value={"MM-DD-YYYY"}>MM-DD-YYYY</MenuItem>
                                        <MenuItem value={"DD-MM-YYYY"}>DD-MM-YYYY</MenuItem>
                                        <MenuItem value={"YYYY-MM-DD"}>YYYY-MM-DD</MenuItem>
                                    </Select>
                                </FormControl>
                            </div>
                        </div>

                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
                            <div>
                                <Typography variant='h6' gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Time Format </Typography>
                            </div>
                            <div>
                                <FormControl fullWidth>
                                    <InputLabel id="demo-simple-select-label">Time Format</InputLabel>
                                    <Select
                                        labelId="demo-simple-select-label"
                                        id="demo-simple-select"
                                        value={timeFormat}
                                        label="Time Format"
                                        onChange={handleChangeTimeFormat}
                                        sx={{ minWidth: "180px", height: 50 }}
                                    >
                                        {/* <MenuItem value="hh:mm A">12-hour (hh:mm AM/PM)</MenuItem>
                                        <MenuItem value="HH:mm">24-hour (HH:mm)</MenuItem> */}
                                        <MenuItem value="hh:mm A">12-hour</MenuItem>
                                        <MenuItem value="HH:mm">24-hour</MenuItem>
                                    </Select>
                                </FormControl>
                            </div>
                        </div>

                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: "10px" }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>Theme</Typography>
                            </div>
                            <div>
                                <FormControl fullWidth>
                                    <InputLabel id="demo-simple-select-label">Theme</InputLabel>
                                    <Select
                                        labelId="demo-simple-select-label"
                                        id="demo-simple-select"
                                        value={themeColor}
                                        label="Theme"
                                        onChange={handleThemeSelection}
                                        sx={{ minWidth: "180px", height: "50px" }}
                                    >
                                        <MenuItem value={"Airstar"}>Airstar</MenuItem>
                                        <MenuItem value={"Space"}>AirstarSpace</MenuItem>
                                        <MenuItem value={"Boat"}>AirstarBoat</MenuItem>
                                        <MenuItem value={"Car"}>AirstarCar</MenuItem>
                                        <MenuItem value={"Driveswaps"}>DriveSwaps</MenuItem>
                                        <MenuItem value={"Nairobi"}>Nairobi</MenuItem>
                                        <MenuItem value={"Studio"}>Studio</MenuItem>
                                        <MenuItem value={"Karibu"}>Karibu</MenuItem>
                                        <MenuItem value={"Fitnest"}>Fitnest</MenuItem>
                                        <MenuItem value={"Adstar"}>Adstar</MenuItem>
                                        <MenuItem value={"Purplerooms"}>PurpleRooms</MenuItem>
                                    </Select>
                                </FormControl>
                            </div>
                        </div>

                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: "10px" }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                                    Limit Listing Images
                                </Typography>
                            </div>
                            <div>
                                <FormControl fullWidth>
                                    <InputLabel id="demo-simple-select-label">Limit Images</InputLabel>
                                    <Select
                                        labelId="demo-simple-select-label"
                                        id="demo-simple-select"
                                        value={limitImages}
                                        label="Limit Images"
                                        onChange={handlelistingImages}
                                        sx={{ minWidth: "180px", height: "50px" }}
                                    >
                                        {limitOptions.map(option => (
                                            <MenuItem key={option} value={option}>
                                                {option.charAt(0).toUpperCase() + option.slice(1)}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: "10px" }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                                    Primary Theme
                                </Typography>
                            </div>
                            <div>
                                <FormControl fullWidth sx={{ minWidth: '180px' }}>
                                    <Box
                                        sx={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            border: '1px solid #ccc',
                                            borderRadius: '4px',
                                            padding: '5px 10px',
                                            height: '50px',
                                            cursor: 'pointer',
                                            position: 'relative',
                                        }}
                                    >
                                        <input
                                            type="color"
                                            value={primaryTheme}
                                            onChange={handlePrimaryTheme}
                                            style={{
                                                width: '100%',
                                                height: '100%',
                                                border: 'none',
                                                background: 'none',
                                                cursor: 'pointer',
                                                outline: 'none',
                                                appearance: 'none',
                                            }}
                                        />
                                    </Box>
                                </FormControl>
                            </div>
                        </div>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: "10px" }}>
                            <div>
                                <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                                    Secondary Theme
                                </Typography>
                            </div>
                            <div>
                                <FormControl fullWidth sx={{ minWidth: '180px' }}>
                                    <Box
                                        sx={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            border: '1px solid #ccc',
                                            borderRadius: '4px',
                                            padding: '5px 10px',
                                            height: '50px',
                                            cursor: 'pointer',
                                            position: 'relative',
                                        }}
                                    >
                                        <input
                                            type="color"
                                            value={secondaryTheme}
                                            onChange={handleSecondaryTheme}
                                            style={{
                                                width: '100%',
                                                height: '100%',
                                                border: 'none',
                                                background: 'none',
                                                cursor: 'pointer',
                                                outline: 'none',
                                                appearance: 'none',
                                            }}
                                        />
                                    </Box>
                                </FormControl>
                            </div>
                        </div>


                    </Card>
                    <Grid container justifyContent="flex-end" sx={{ paddingRight: '20px', bottom: '10px' }}>
                        <Button variant="contained" onClick={editSettings}>
                            Save
                        </Button>
                    </Grid>
                </>
            }
        </>
    )
} 